<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { FileText, FileUp, Plus, Save, X } from 'lucide-vue-next'
import StatusBadge from '../components/common/StatusBadge.vue'
import { useReportStore } from '../stores/report.store'
import { useAuthStore } from '../stores/auth.store'
import { useDispatchStore } from '../stores/dispatch.store'
import { useIncidentStore } from '../stores/incident.store'
import { useAuditStore } from '../stores/audit.store'

const reportStore = useReportStore(); const authStore = useAuthStore(); const dispatchStore = useDispatchStore(); const incidentStore = useIncidentStore(); const auditStore = useAuditStore()
const institutionId = computed(()=>authStore.user?.institucionId ?? 'INS-001')
const formOpen = ref(false); const attachment = ref<File|null>(null); const savedMessage = ref('')
const myReports = computed(()=>reportStore.reports.filter((item)=>item.institutionId===institutionId.value))
const eligibleIncidents = computed(()=>dispatchStore.dispatches.filter((item)=>item.institutionId===institutionId.value).map((item)=>item.incidentId))
const emptyForm=()=>({incidentId:eligibleIncidents.value[0] ?? 'INC-003',institutionId:institutionId.value,fechaIncidente:'2026-09-13',horaRecepcion:'14:05',horaSalida:'14:07',horaLlegada:'14:14',horaControl:'14:28',horaFinalizacion:'14:45',personal:4,vehiculos:1,personasAfectadas:0,personasEvacuadas:0,heridos:0,fallecidos:0,danosMateriales:'',causa:'',acciones:'',observaciones:'',recomendaciones:''})
const form=reactive(emptyForm())
const selectFile=(event:Event)=>{attachment.value=(event.target as HTMLInputElement).files?.[0]??null}
const minutesBetween=(a:string,b:string)=>{if(!a||!b)return 0;const [ah,am]=a.split(':').map(Number);const [bh,bm]=b.split(':').map(Number);return Math.max(0,(bh*60+bm)-(ah*60+am))}
const responseMinutes=computed(()=>minutesBetween(form.horaRecepcion,form.horaLlegada));const totalMinutes=computed(()=>minutesBetween(form.horaRecepcion,form.horaFinalizacion))
const openForm=()=>{Object.assign(form,emptyForm());attachment.value=null;savedMessage.value='';formOpen.value=true}
const save=async()=>{const created=await reportStore.createReport({...form,status:'COMPLETADO',attachments:attachment.value?[{id:`ATT-${Date.now()}`,nombre:attachment.value.name,tipo:attachment.value.type,tamano:attachment.value.size,fecha:new Date().toISOString()}]:[]});await auditStore.addLog({usuario:authStore.user?.nombre ?? 'Admin institución',accion:'Registró informe de atención',incidenteId:created.incidentId,detalle:`Informe ${created.id} guardado con datos estructurados.`});savedMessage.value='Informe guardado correctamente en modo demostración.';formOpen.value=false}
const incidentFor=(id:string)=>incidentStore.incidents.find((item)=>item.id===id)
onMounted(async()=>{await Promise.all([reportStore.fetchReports(),dispatchStore.fetchDispatches(),incidentStore.fetchIncidents(),auditStore.fetchLogs()])})
</script>
<template><div class="space-y-6"><section class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-[10px] font-semibold uppercase tracking-[0.24em] text-orange-500">Administración institucional</p><h2 class="mt-2 text-2xl font-semibold text-slate-900">Informes de Atención</h2><p class="mt-2 max-w-3xl text-sm text-slate-600">Los datos se almacenan de forma estructurada para futuras métricas; el PDF queda como respaldo documental.</p></div><button class="inline-flex items-center justify-center gap-2 rounded-xl bg-[#f24a23] px-4 py-3 text-sm font-semibold text-white" @click="openForm"><Plus class="h-4 w-4"/> Nuevo informe</button></section><div v-if="savedMessage" class="rounded-2xl border border-emerald-200 bg-emerald-50 p-4 text-sm font-medium text-emerald-800">{{ savedMessage }}</div><section class="grid gap-4 lg:grid-cols-2"><article v-for="report in myReports" :key="report.id" class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div class="flex items-start justify-between gap-3"><div class="flex h-10 w-10 items-center justify-center rounded-xl bg-[#f6efe7] text-orange-600"><FileText class="h-5 w-5"/></div><StatusBadge :state="report.status" :tone="report.status==='REVISADO'||report.status==='COMPLETADO'?'success':'warning'">{{ report.status }}</StatusBadge></div><p class="mt-4 text-xs font-semibold uppercase tracking-[0.16em] text-slate-500">{{ report.id }} · {{ report.incidentId }}</p><h3 class="mt-2 font-semibold text-slate-900">{{ incidentFor(report.incidentId)?.ubicacion || 'Incidente registrado' }}</h3><div class="mt-4 grid grid-cols-2 gap-3 text-sm"><div class="rounded-xl bg-slate-50 p-3"><span class="text-xs text-slate-500">Personal</span><p class="mt-1 font-semibold text-slate-900">{{ report.personal }}</p></div><div class="rounded-xl bg-slate-50 p-3"><span class="text-xs text-slate-500">Vehículos</span><p class="mt-1 font-semibold text-slate-900">{{ report.vehiculos }}</p></div></div><p class="mt-4 text-xs text-slate-500">Adjuntos: {{ report.attachments.map((item)=>item.nombre).join(', ') || 'Sin PDF' }}</p></article><div v-if="myReports.length===0" class="rounded-2xl border border-dashed border-slate-300 bg-white p-10 text-center text-sm text-slate-500 lg:col-span-2">Aún no se registraron informes de atención.</div></section>

<div v-if="formOpen" class="fixed inset-0 z-[80] overflow-y-auto bg-slate-900/25 p-4 backdrop-blur-sm"><div class="mx-auto my-6 max-w-4xl rounded-2xl border border-slate-200 bg-white p-6 shadow-2xl"><div class="flex items-start justify-between gap-3"><div><p class="text-[10px] font-semibold uppercase tracking-[0.18em] text-orange-500">Nuevo informe</p><h3 class="mt-1 text-xl font-semibold text-slate-900">Registro posterior a la atención</h3></div><button class="rounded-lg p-2 text-slate-500" @click="formOpen=false"><X class="h-5 w-5"/></button></div><form class="mt-6 grid gap-5 md:grid-cols-2" @submit.prevent="save"><label class="text-sm font-medium text-slate-700">Incidente<select v-model="form.incidentId" class="mt-2 w-full rounded-xl border border-slate-200 px-3 py-2.5"><option v-for="id in eligibleIncidents" :key="id" :value="id">{{ id }} · {{ incidentFor(id)?.ubicacion }}</option></select></label><label class="text-sm font-medium text-slate-700">Fecha del incidente<input v-model="form.fechaIncidente" type="date" class="mt-2 w-full rounded-xl border border-slate-200 px-3 py-2.5"/></label><label v-for="field in ['horaRecepcion','horaSalida','horaLlegada','horaControl','horaFinalizacion']" :key="field" class="text-sm font-medium capitalize text-slate-700">{{ field.replace(/([A-Z])/g,' $1') }}<input v-model="form[field as keyof typeof form]" type="time" class="mt-2 w-full rounded-xl border border-slate-200 px-3 py-2.5"/></label><div class="rounded-xl border border-emerald-200 bg-emerald-50 p-4"><p class="text-xs uppercase tracking-[0.14em] text-emerald-700">Tiempo de respuesta</p><p class="mt-1 text-2xl font-semibold text-slate-900">{{ responseMinutes }} min</p></div><div class="rounded-xl border border-orange-200 bg-orange-50 p-4"><p class="text-xs uppercase tracking-[0.14em] text-orange-700">Duración total</p><p class="mt-1 text-2xl font-semibold text-slate-900">{{ totalMinutes }} min</p></div><label v-for="field in ['personal','vehiculos','personasAfectadas','personasEvacuadas','heridos','fallecidos']" :key="field" class="text-sm font-medium capitalize text-slate-700">{{ field.replace(/([A-Z])/g,' $1') }}<input v-model.number="form[field as keyof typeof form]" type="number" min="0" class="mt-2 w-full rounded-xl border border-slate-200 px-3 py-2.5"/></label><label v-for="field in ['danosMateriales','causa','acciones','observaciones','recomendaciones']" :key="field" class="text-sm font-medium capitalize text-slate-700 md:col-span-2">{{ field.replace(/([A-Z])/g,' $1') }}<textarea v-model="form[field as keyof typeof form]" rows="3" class="mt-2 w-full rounded-xl border border-slate-200 px-3 py-2.5"></textarea></label><label class="flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-slate-300 p-4 text-sm text-slate-700 md:col-span-2"><FileUp class="h-5 w-5 text-orange-600"/><span>{{ attachment ? `${attachment.name} · ${(attachment.size/1024).toFixed(1)} KB` : 'Adjuntar PDF de respaldo' }}</span><input type="file" accept="application/pdf" class="hidden" @change="selectFile"/></label><button class="inline-flex items-center justify-center gap-2 rounded-xl bg-[#f24a23] px-4 py-3 text-sm font-semibold text-white md:col-span-2"><Save class="h-4 w-4"/> Guardar informe</button></form></div></div>
</div></template>
